import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第66章 同一秒","description":"","frontmatter":{},"headers":[],"relativePath":"第66章_同一秒.md","filePath":"第66章_同一秒.md"}'),_={name:"第66章_同一秒.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第66章-同一秒" tabindex="-1">第66章 同一秒 <a class="header-anchor" href="#第66章-同一秒" aria-label="Permalink to &quot;第66章 同一秒&quot;">​</a></h1><p>那年我们找到了一个时差进不去的地方。</p><p>游戏。</p><p>她那边开始玩一个游戏，打中路。</p><p>她是在四月里跟我说的，她说她买了新手机，说这个手机打团不掉帧。</p><p>我说，你原来那个不是也能打。</p><p>她说，能，但是卡。</p><p>我说，多少钱。</p><p>她说，你别问钱。</p><p>我说，我就是问问。</p><p>她说，你每次问钱就是在算你差多少。</p><p>我说，对。</p><p>她说，那你别算了，我看着难受。</p><p>三月末我们试过打一次。</p><p>那次很乱。</p><p>她那边周六晚上八点，我这边周日凌晨三点。</p><p>我知道这个点，因为我算过一次之后，我从此每周日都三点起。</p><p>第一次她带我进那个游戏，是在高一。</p><p>那次她说的是&quot;跟着我&quot;。</p><p>三个字。</p><p>那天她把号开出来，说，你走我后面，你别出去，你出去就死。</p><p>我说，好。</p><p>我说，你在哪儿。</p><p>她说，我在你前面。</p><p>那是我第一次知道，有人会在前面。</p><p>五年以后，我们在同一个游戏的同一张地图里。</p><p>她还是在前面。</p><p>还是中路。</p><p>她说，你走我后面。</p><p>我说，好。</p><p>她说，你别贪。</p><p>我说，嗯。</p><p>她说，你又嗯。</p><p>我说，我在看你血。</p><p>她说，你看我血干什么，你看地图。</p><p>我说，地图我看了。</p><p>她说，你看了你刚才为什么没信号。</p><p>我说，我在看你有没有蓝。</p><p>她那一局没骂我。</p><p>下一局她开始骂。</p><p>她说，你刚才那个大招为什么放早了。</p><p>我说，我怕你打不死。</p><p>她说，你要是不放，我等我队友到就死了。</p><p>我说，那我不放我怎么知道你等不等。</p><p>她说，你相信我一次不行吗。</p><p>我说，我行。</p><p>她说，那你下把别放。</p><p>下把她死了。</p><p>死之前她喊了一声，喊得很响。</p><p>她那边的室友肯定听见了。</p><p>我说，你怎么了。</p><p>她说，我被抓了。</p><p>我说，我看到了。</p><p>她说，你看到你怎么不来。</p><p>我说，我来了我死了两个人都死。</p><p>她说，你死了我不就活了吗。</p><p>我说，这是什么道理。</p><p>她说，这是中路的道理。</p><p>她说，你不懂，你一个打下的懂什么。</p><p>那段时间我每天晚上要看两个小时的录像。</p><p>我看她打。</p><p>我拿一个本子记：她这个点喜欢往哪走，她没蓝的时候往哪撤，她被包的时候第一反应是往前还是往后。</p><p>我记了四十多页。</p><p>后来我不用看地图了。</p><p>她说，你今天怎么知道来。</p><p>我说，你刚才那个位置只有这一个走法。</p><p>她说，哦。</p><p>她说，你偷偷练了。</p><p>我说，没有。</p><p>她说，你练了你不说。</p><p>我说，我练了。</p><p>她说，你练这个干什么。</p><p>我说，我不能总让你说&quot;跟着我&quot;。</p><p>她那天没回。</p><p>过了很久，她回了一句。</p><p>她说，你把这句话发给谁都不好。</p><p>我说，为什么。</p><p>她说，因为这是实话。</p><p>四月末有一局，她掉了。</p><p>打到一半，她的人物忽然站在中路不动。</p><p>我那时候在她后面，我看见她血条上面那个小图标变成了灰色。</p><p>我说，你卡了？</p><p>没人回。</p><p>我们那个打野在团队里打了一个“？”。</p><p>他说，中路呢。</p><p>我说，她掉了。</p><p>他说，那你走啊，你推塔。</p><p>我没动。</p><p>我把我的人物站在她旁边。</p><p>她那里还剩半管血。</p><p>对面中路过来一个人，把我杀了。</p><p>我死了以后我回泉水，我买了一个回城的道具。</p><p>我没有走。</p><p>我在泉水里站着，等她那一个人回来。</p><p>我们那个打野开始骂。</p><p>他打字：你干嘛呢。</p><p>我说，我在等一个人。</p><p>他说，等什么，排位呢。</p><p>我说，那把这局输了吧。</p><p>他打了很多字。</p><p>我不看了。</p><p>那天她在第三十七分钟回来的。</p><p>她回来的第一句是：对不起，我们这里停电了。</p><p>她说，现在又来了。</p><p>她说，你还在吗。</p><p>我说，在。</p><p>她说，你刚才在干什么。</p><p>我说，我在泉水里站着。</p><p>她说，那不就挂机了吗。</p><p>我说，对。</p><p>她说，扣了多少分。</p><p>我说，十七。</p><p>她隔了很久。</p><p>她说，你这个人。</p><p>她说，你为什么不等我回来再开。</p><p>我说，因为下一把我不知道什么时候能等到你。</p><p>那三个月里，是我们这一辈子唯一一段“同一分钟”。</p><p>打字的时候我们从来不在同一分钟。</p><p>我发出去，她三小时后看。</p><p>可是游戏里不是。</p><p>游戏里她放技能的那一秒，我按下的那一秒，是同一秒。</p><p>我们两个在那张图上，是同时在的。</p><p>我那时候不知道这个有多稀。</p><p>五月有一局，我们打得很顺。</p><p>她中路拿了四杀，她在麦克风里&quot;啊&quot;了一声，很短。</p><p>那是我第一次听见她出声。</p><p>不是语音，是她打游戏的时候会不自觉叫一声。</p><p>那一声只有半个字。</p><p>打完她打字：你看到我四杀没有。</p><p>我说，看到了。</p><p>她说，你怎么不夸我。</p><p>我说，你今天很厉害。</p><p>她说，这话太干了。</p><p>我说，那我重新说。</p><p>她说，你别重新说，你说出来更干。</p><p>我说，那你教我。</p><p>她说，你等着。</p><p>她隔了半分钟，发了一句。</p><p>她说，我男朋友今天四杀，我很高兴。</p><p>我看到这一句，坐在椅子上。</p><p>那是我们认识六年，她第一次在没有任何前缀、没有任何&quot;开玩笑&quot;的情况下，打出那三个字。</p><p>我打：你刚才那句话，是不是在宿舍。</p><p>她说，是。</p><p>我说，你旁边有人吗。</p><p>她说，有。</p><p>我说，那你敢发。</p><p>她说，我就发一次。</p><p>她说，你不用回。</p><p>我说，我要回。</p><p>她说，你回什么。</p><p>我那天回的是：我看见了。</p><p>她说，行。</p><p>她说，那你记住这个就行。</p><p>那一晚我们打完最后一局，她那边凌晨一点。</p><p>我这边上午九点。</p><p>她最后发了一句。</p><p>她说，你今天怎么不问我几点睡。</p><p>我说，我怕你说完你妈在。</p><p>她说，你今天话少。</p><p>我说，我在想那句话。</p><p>她说，哪句。</p><p>我说，你不用回那句。</p><p>她说，那你现在在干什么。</p><p>我说，我在食堂。</p><p>我说，今天的粥卖完了，我在吃馒头。</p><p>她说，那你多吃点。</p><p>我说，嗯。</p><p>她说，你又开始嗯了。</p><p>很多年以后，我才知道那个游戏为什么对我们两个那么重要。</p><p>因为那是唯一一个地方，她说&quot;跟着我&quot;，而我可以真的跟上。</p><p>现实生活里，她说&quot;跟着我&quot;的第二天，她妈会把她的手机收走。</p>',171)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
